/// Counts `invalidate_all` calls.
#[derive(Default)]
struct Counting(AtomicUsize);

impl Counting {
    fn get(&self) -> usize {
        self.0.load(Ordering::SeqCst)
    }
}

impl Invalidate for Counting {
    fn invalidate_all(&self) {
        self.0.fetch_add(1, Ordering::SeqCst);
    }
}
